package io.ledgerflow.payment.domain.model;

import io.ledgerflow.events.Money;
import io.ledgerflow.events.WalletRef;

import java.util.List;
import java.util.UUID;

public sealed interface PaymentState {

    UUID paymentId();

    record Requested(UUID paymentId, List<WalletRef> wallets, Money total)          implements PaymentState {}
    record FundsHeld(UUID paymentId, UUID holdId, Money total)              implements PaymentState {}
    record AuthorizationPending(UUID paymentId, UUID holdId, UUID authorizationId)          implements PaymentState {}
    record CapturePending(UUID paymentId, UUID holdId, UUID authorizationId)          implements PaymentState {}
    record Captured(UUID paymentId, List<UUID> captures)                        implements PaymentState {}
    record Compensating(UUID paymentId, FailureReason reason, Step failedAt)    implements PaymentState {}
    record Failed(UUID paymentId, FailureReason reason)                         implements PaymentState {}

    enum Step { RESERVE, AUTHORIZE, ISSUE }
    enum FailureReason { PAYMENT_DECLINED, ISSUE_FAILED, TIMED_OUT, WALLETS_UNAVAILABLE }
}

package io.ledgerflow.payment.application;

import io.ledgerflow.payment.domain.model.PaymentState;
import io.ledgerflow.payment.domain.model.PaymentState.*;

import java.util.List;

/** Pure: state + event in, next state + commands out. No IO, no Spring. */
public final class PaymentSaga {

    public record Decision(PaymentState next, List<Command> commands) {}

    public static Decision on(PaymentState state, SagaEvent event) {
        return switch (state) {

            case Requested r -> switch (event) {
                case FundsHeld e  -> new Decision(
                        new AuthorizationPending(r.paymentId(), e.holdId(), null),
                        List.of(new Command.AuthorizePayment(r.paymentId(), r.total())));
                case Rejected e       -> fail(r, FailureReason.WALLETS_UNAVAILABLE);
                default               -> ignore(r);
            };

            case AuthorizationPending p -> switch (event) {
                case PaymentAuthorized e -> new Decision(
                        new CapturePending(p.paymentId(), p.holdId(), e.authorizationId()),
                        List.of(new Command.IssueCaptures(p.paymentId(), p.holdId())));
                case PaymentDeclined e   -> compensate(p, FailureReason.PAYMENT_DECLINED, Step.AUTHORIZE);
                case StepTimedOut e      -> compensate(p, FailureReason.TIMED_OUT, Step.AUTHORIZE);
                default                  -> ignore(p);
            };

            case CapturePending t -> switch (event) {
                case Captured e -> new Decision(
                        new Captured(t.paymentId(), e.captureIds()), List.of());
                case IssueFailed e   -> compensate(t, FailureReason.ISSUE_FAILED, Step.ISSUE);
                default              -> ignore(t);
            };

            // terminal states absorb late replies instead of blowing up
            case Captured c    -> ignore(c);
            case Failed f       -> ignore(f);
            case Compensating c -> onCompensating(c, event);
        };
    }

    /** A reply that arrived after we moved on. Discard it, do not fail. */
    private static Decision ignore(PaymentState s) { return new Decision(s, List.of()); }
}

@Scheduled(fixedDelay = 1000)
@Transactional
void sweepExpiredSteps() {
    for (var saga : sagas.claimExpired(Instant.now())) {   // FOR UPDATE SKIP LOCKED
        apply(saga.paymentId(), new StepTimedOut(saga.currentStep()));
    }
}
